def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    import re

    token_pattern = re.compile(
        r"[0-9]+|[A-Z]+[0-9]*|<>|<=|>=|[-+*/(),:=<>]"
    )
    functions = {"SUM", "MIN", "MAX", "IF"}
    precedence = {
        "=": 0, "<>": 0, "<": 0, "<=": 0, ">": 0, ">=": 0,
        "+": 1, "-": 1,
        "*": 2, "/": 2,
        "neg": 3,
        ":": 4,
    }

    def integer(text):
        # Chunk conversion also supports literals beyond Python's digit limit.
        negative = text.startswith("-")
        if text[0] in "+-":
            text = text[1:]
        value = 0
        for offset in range(0, len(text), 9):
            chunk = text[offset:offset + 9]
            value = value * (10 ** len(chunk)) + int(chunk)
        return -value if negative else value

    def parse(formula):
        nodes = []
        operators = []
        expect_operand = True

        def reduce_operator():
            op = operators.pop()
            if op == "neg":
                nodes.append(("neg", nodes.pop()))
            else:
                right = nodes.pop()
                left = nodes.pop()
                nodes.append((op, left, right))

        for token in token_pattern.findall(formula):
            if token[0].isdigit():
                nodes.append(("number", integer(token)))
                expect_operand = False
            elif token in functions:
                operators.append([token, 1])
                expect_operand = True
            elif token[0].isalpha():
                nodes.append(("reference", token))
                expect_operand = False
            elif token == "(":
                operators.append("(")
                expect_operand = True
            elif token == ",":
                while operators[-1] != "(":
                    reduce_operator()
                operators[-2][1] += 1
                expect_operand = True
            elif token == ")":
                while operators[-1] != "(":
                    reduce_operator()
                operators.pop()

                if operators and isinstance(operators[-1], list):
                    name, count = operators.pop()
                    arguments = tuple(nodes[-count:])
                    del nodes[-count:]
                    nodes.append((name, arguments))
                expect_operand = False
            elif token == "-" and expect_operand:
                operators.append("neg")
            else:
                while (
                    operators
                    and isinstance(operators[-1], str)
                    and operators[-1] != "("
                    and precedence[operators[-1]] >= precedence[token]
                ):
                    reduce_operator()
                operators.append(token)
                expect_operand = True

        while operators:
            reduce_operator()
        return nodes[0]

    def function_terms(arguments):
        for argument in arguments:
            if argument[0] != ":":
                yield argument
                continue

            first = argument[1][1]
            last = argument[2][1]
            col1, col2 = sorted((ord(first[0]), ord(last[0])))
            row1, row2 = sorted((int(first[1:]), int(last[1:])))

            for row in range(row1, row2 + 1):
                for column in range(col1, col2 + 1):
                    name = chr(column) + str(row)
                    if name in cells:
                        yield ("reference", name)

    results = {}
    visiting = set()

    for root in cells:
        if root in results:
            continue

        stack = [("cell", root)]
        value = 0

        while stack:
            task = stack.pop()
            action = task[0]

            if action == "cell":
                name = task[1]
                if name in results:
                    value = results[name]
                elif name not in cells:
                    value = 0
                elif name in visiting:
                    value = "#CYCLE!"
                else:
                    content = cells[name]
                    if content.startswith("="):
                        visiting.add(name)
                        stack.append(("save", name))
                        stack.append(("evaluate", parse(content[1:])))
                    else:
                        value = integer(content)
                        results[name] = value

            elif action == "save":
                name = task[1]
                results[name] = value
                visiting.remove(name)

            elif action == "evaluate":
                node = task[1]
                kind = node[0]

                if kind == "number":
                    value = node[1]
                elif kind == "reference":
                    stack.append(("cell", node[1]))
                elif kind == "neg":
                    stack.append(("negate",))
                    stack.append(("evaluate", node[1]))
                elif kind == "IF":
                    condition, then_branch, else_branch = node[1]
                    stack.append(("choose", then_branch, else_branch))
                    stack.append(("evaluate", condition))
                elif kind in functions:
                    stack.append(
                        ("next_argument", kind, function_terms(node[1]), None)
                    )
                else:
                    stack.append(("left_done", kind, node[2]))
                    stack.append(("evaluate", node[1]))

            elif action == "negate":
                if not isinstance(value, str):
                    value = -value

            elif action == "left_done":
                if not isinstance(value, str):
                    stack.append(("right_done", task[1], value))
                    stack.append(("evaluate", task[2]))

            elif action == "right_done":
                if isinstance(value, str):
                    continue

                op, left = task[1], task[2]
                right = value

                if op == "+":
                    value = left + right
                elif op == "-":
                    value = left - right
                elif op == "*":
                    value = left * right
                elif op == "/":
                    if right == 0:
                        value = "#DIV/0!"
                    else:
                        quotient = abs(left) // abs(right)
                        value = -quotient if (left < 0) != (right < 0) else quotient
                elif op == "=":
                    value = left == right
                elif op == "<>":
                    value = left != right
                elif op == "<":
                    value = left < right
                elif op == "<=":
                    value = left <= right
                elif op == ">":
                    value = left > right
                elif op == ">=":
                    value = left >= right

            elif action == "choose":
                if not isinstance(value, str):
                    branch = task[1] if value else task[2]
                    stack.append(("evaluate", branch))

            elif action == "next_argument":
                name, iterator, accumulated = task[1:]
                argument = next(iterator, None)
                if argument is None:
                    value = 0 if accumulated is None else accumulated
                else:
                    stack.append(("collect", name, iterator, accumulated))
                    stack.append(("evaluate", argument))

            elif action == "collect":
                if isinstance(value, str):
                    continue

                name, iterator, accumulated = task[1:]
                if accumulated is None:
                    accumulated = value
                elif name == "SUM":
                    accumulated += value
                elif name == "MIN":
                    accumulated = min(accumulated, value)
                else:
                    accumulated = max(accumulated, value)

                stack.append(("next_argument", name, iterator, accumulated))

    return {name: results[name] for name in cells}
